// ---- lib/errors.js ----
// Typed errors for the Sniffies interaction library. Never place a cookie or
// session value in a message — callers surface these to logs/UIs.

/** An HTTP or protocol failure from a Sniffies call. */
class SniffiesError extends Error {
  /**
   * @param {string} message human-readable summary (no secrets)
   * @param {{status?:number, path?:string, base?:string}} [meta]
   */
  constructor(message, { status = 0, path = '', base = '' } = {}) {
    super(message);
    this.name = 'SniffiesError';
    this.status = status;
    this.path = path;
    this.base = base;
  }
}

/** Raised when every candidate API base failed for a request. */
class SniffiesAllBasesError extends SniffiesError {
  /**
   * @param {string} path
   * @param {Array<{base:string, error:Error}>} attempts
   */
  constructor(path, attempts = []) {
    super(`All API bases failed for ${path}`, { status: 0, path });
    this.name = 'SniffiesAllBasesError';
    this.attempts = attempts;
  }
}

/** Raised when a request is aborted by the fetch timeout. */
class SniffiesTimeoutError extends SniffiesError {
  constructor(path, ms) {
    super(`Request timed out after ${ms}ms: ${path}`, { status: 0, path });
    this.name = 'SniffiesTimeoutError';
    this.timeoutMs = ms;
  }
}


// ---- lib/limiter.js ----
// Opt-in rate limiter mirroring the userscript's profile-fetch posture
// (MAX_REQUESTS_PER_MIN = 6, COOLDOWN_MS = 10 min). Sniffies throttles/blocks
// abusive clients, so callers issuing many profile fetches should route them
// through here: calls are serialized behind a minimum interval and a rolling
// per-minute cap, and a caller-reported server rejection opens a cooldown gate.

/**
 * @param {{maxPerMinute?:number, minIntervalMs?:number, cooldownMs?:number}} [opts]
 * @returns {{run:(fn:()=>Promise<any>)=>Promise<any>, reportRejection:()=>void,
 *            cooldownRemainingMs:()=>number, pending:()=>number}}
 */
function createLimiter({ maxPerMinute = 6, minIntervalMs = 1_000, cooldownMs = 600_000 } = {}) {
  let chain = Promise.resolve();
  let lastAt = 0;
  let size = 0;
  let cooldownUntil = 0;
  const stamps = [];
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  async function gate() {
    let now = Date.now();
    if (now < cooldownUntil) await sleep(cooldownUntil - now);
    now = Date.now();
    while (stamps.length && now - stamps[0] > 60_000) stamps.shift();
    if (stamps.length >= maxPerMinute) {
      const wait = 60_000 - (now - stamps[0]);
      if (wait > 0) await sleep(wait);
    }
    now = Date.now();
    const since = now - lastAt;
    if (since < minIntervalMs) await sleep(minIntervalMs - since);
    lastAt = Date.now();
    stamps.push(lastAt);
  }

  function run(fn) {
    size += 1;
    const p = chain.then(async () => {
      try { await gate(); return await fn(); }
      finally { size -= 1; }
    });
    chain = p.catch(() => {});
    return p;
  }

  /** Call when the server signals throttling (429/403): pauses the queue for cooldownMs. */
  const reportRejection = () => { cooldownUntil = Date.now() + cooldownMs; };

  return {
    run,
    reportRejection,
    cooldownRemainingMs: () => Math.max(0, cooldownUntil - Date.now()),
    pending: () => size,
  };
}


// ---- lib/api.js ----
// Sniffies HTTP client: the two profile endpoints the site exposes to a same-browser caller.
// Auth is cookies only (`credentials: "include"`) — no token header exists; a library caller
// inherits the logged-in browser session and cannot authenticate outside the browser.

const DEFAULT_PARTIALS_BASES = [
  'https://usw.api.sniffies.com/api/user/partials',
  'https://uswapi2.sniffies.com/api/user/partials',
];
const DEFAULT_FULL_ORIGINS = [
  'https://usw.api.sniffies.com',
  'https://uswapi2.sniffies.com',
  'https://uswapi.sniffies.com',
];
